Lemma round fx R p :
  getr R (reg 2) = Z_to_bv 64 sp -> getr R (reg 10) = Z_to_bv 64 b -> getr R (reg 11) = Z_to_bv 64 p -> getr R (reg 13) = Z_to_bv 64 32 ->
